package com.cpf.gateway.runtime;
import com.cpf.core.api.runtimecontrol.*;import java.time.Instant;import java.util.*;
public final class CpfApiClientSecurityRuntimeApplier implements CpfRuntimeChangeApplier{
 private final CpfApiClientSecurityPolicy policy;public CpfApiClientSecurityRuntimeApplier(CpfApiClientSecurityPolicy policy){this.policy=policy;}
 public String changeType(){return "API_CLIENT";}public boolean supportsIdempotentReplay(){return true;}public boolean snapshotCapable(){return true;}
 @SuppressWarnings("unchecked")public CpfRuntimeApplyResult apply(CpfRuntimeDelivery d){try{Object raw=d.payload().get("clients");if(!(raw instanceof List<?>list))throw new IllegalArgumentException("clients array 필수");LinkedHashMap<String,CpfApiClientSecurityPolicy.Client>m=new LinkedHashMap<>();for(Object item:list){if(!(item instanceof Map<?,?>r))throw new IllegalArgumentException("client object 필요");Map<String,Object>v=(Map<String,Object>)r;String id=req(v,"clientId");Instant expiry=v.get("expiresAt")==null?null:Instant.parse(String.valueOf(v.get("expiresAt")));m.put(id,new CpfApiClientSecurityPolicy.Client(id,req(v,"keyHash"),bool(v,"active",true),set(v.get("allowedIpCidrs")),set(v.get("certificateSerials")),expiry,(int)num(v.get("quotaPermits"),0),num(v.get("quotaWindowMillis"),60000),set(v.get("authorities"))));}policy.replace(d.desiredVersion(),m);return CpfRuntimeApplyResult.success(d.payloadHash());}catch(RuntimeException e){return CpfRuntimeApplyResult.failure("API_CLIENT_INVALID","API client key/quota/IP/cert/expiry 정책 오류");}}
 private String req(Map<String,Object>m,String k){Object v=m.get(k);if(v==null||String.valueOf(v).isBlank())throw new IllegalArgumentException(k+" 필수");return String.valueOf(v).trim();}private boolean bool(Map<String,Object>m,String k,boolean f){Object v=m.get(k);return v instanceof Boolean b?b:v==null?f:Boolean.parseBoolean(String.valueOf(v));}private long num(Object v,long f){return v instanceof Number n?n.longValue():v==null?f:Long.parseLong(String.valueOf(v));}private Set<String>set(Object v){if(!(v instanceof List<?>l))return Set.of();LinkedHashSet<String>s=new LinkedHashSet<>();for(Object x:l)if(x!=null)s.add(String.valueOf(x));return Set.copyOf(s);}
}
